// ne_glyph_tro.go — the trees away from full resolution (docs/ne-glyph.md §Trees far out).
// With the trees on and no crown sheet to show (full resolution off, or closer than it but
// below HI_TREE) the map carries one green sheet: a hexagon per H3 cell of the observed-layer
// peer's stand index, greener = more tree tops per hectare — res 7 for Austria, res 8 / 9
// for a box small enough (ne_tree_stands.go, /api/v1/ne/glyph/trees). A quiet chip in the
// map's corner counts the trees in view.
package main

// neGlyphTroCSS — the sheet and the corner chip (the chip wears the height scale's glass).
const neGlyphTroCSS = `
svg.trspark{display:inline-block;width:3em;height:.8em;vertical-align:baseline;margin:0 .1em;overflow:visible}svg.trspark rect{fill:currentColor;opacity:.5}.trspark-r{color:var(--mut);font-size:.92em;white-space:nowrap}
svg.glyph .tro{pointer-events:none}svg.glyph .tro path{fill:#2f9e58;stroke:none}@media(prefers-color-scheme:dark){svg.glyph .tro path{fill:#58c97c}}
/* the corner count wears the in-view note's clothes (.gt-n.iv / .gt-ivb): same type, pad, rule, radius and ground, in the same corner — it stands in for the note where there is none (full resolution off); with the note up the count rides in it (troNote) */
.glyph-trn{position:absolute;right:8px;bottom:calc(8px + var(--tip-h,0px));z-index:3;display:inline-flex;align-items:center;gap:.4em;max-width:calc(100% - 16px);box-sizing:border-box;padding:.15em .55em .15em .45em;font-size:var(--fz2);line-height:1.4;color:var(--mut);white-space:nowrap;border:1px solid var(--rule);border-radius:3px;background:color-mix(in srgb,var(--bg) 92%,transparent);-webkit-backdrop-filter:blur(4px);backdrop-filter:blur(4px);opacity:0;pointer-events:none;transition:opacity .3s;font-variant-numeric:tabular-nums}
.glyph-trn.on{opacity:1}figure.glyph.fs .glyph-trn{right:calc(8px + env(safe-area-inset-right,0px));-webkit-backdrop-filter:none;backdrop-filter:none}.glyph-trn svg{flex:none;width:1.1em;height:1.1em;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;opacity:.8;color:var(--fg)}.glyph-trn b{color:var(--fg);font-weight:400}.glyph-trn span{overflow:hidden;text-overflow:ellipsis}
@media(max-width:640px){.glyph-trn .w0{display:none}}
`

// neGlyphTroJS — runs inside the glyph IIFE (after the filter block: it reads its helpers).
const neGlyphTroJS = `
/* ── trees far out: the stand index as one green sheet ── */
var TRO_B=8,TRO_A=.85,TRO_D=260/* tree tops per ha that read as full ink */,TRO_A9=.2,TRO_A8=1.4/* deg²: neStandsMaxDeg2 */,tro={d:null,ld:false,g:null,pk:'',bx:null,bk:'',bl:'',cache:{},order:[],t:0,el:null,err:0};
function troVis(){return !!proj&&hi.tree&&(!hi.on||W/vb.w<HI_TREE)}
function troBox(){var a=lonlat(vb.x,vb.y+vb.h),b=lonlat(vb.x+vb.w,vb.y),q=function(p){return[Math.floor(a[0]/p)*p,Math.floor(a[1]/p)*p,Math.ceil(b[0]/p)*p,Math.ceil(b[1]/p)*p]},r=q(.1),res=9;if((r[2]-r[0])*(r[3]-r[1])>TRO_A9){r=q(.25);res=8;if((r[2]-r[0])*(r[3]-r[1])>TRO_A8)return null}return res+'|'+r.map(function(v){return v.toFixed(2)}).join(',')}
function troBucket(n,ha){return n>0?Math.max(1,Math.ceil(Math.min(1,Math.pow(n/ha/TRO_D,.8))*TRO_B)):0}
function troSync(){var on=troVis();if(!on){if(tro.g&&tro.pk){tro.g.innerHTML='';tro.pk=''}clearTimeout(tro.t);troChip();return}if(!tro.d&&!tro.ld&&Date.now()-tro.err>30000){tro.ld=true;fetch('/api/v1/ne/glyph/trees',{credentials:'omit'}).then(function(r){if(!r.ok)throw new Error('trees '+r.status);return r.json()}).then(function(d){tro.ld=false;tro.d=d;dbgLog('trees far: '+d.total.trees+' in the index');troPaint();if(picked&&pk&&pk.t==='cell'&&typeof recard==='function')recard();hiLegend()}).catch(function(e){tro.ld=false;tro.err=Date.now();dbgLog('trees far: '+(e&&e.message||e))})}clearTimeout(tro.t);tro.t=setTimeout(troLoad,tro.pk?140:0);troPlace()}
function troLoad(){if(!troVis())return;var k=troBox();tro.bk=k||'';if(!k||(tro.bx&&tro.bx.k===k)){troPaint();return}if(tro.cache[k]){tro.bx=tro.cache[k];troPaint();return}troPaint();if(tro.bl===k)return;tro.bl=k;var p=k.split('|');fetch('/api/v1/ne/glyph/trees?res='+p[0]+'&bbox='+p[1],{credentials:'omit'}).then(function(r){if(!r.ok)throw new Error('trees box '+r.status);return r.arrayBuffer()}).then(function(ab){if(tro.bl===k)tro.bl='';var dv=new DataView(ab),n=dv.getUint32(4,true),b={k:k,n:n,res:dv.getUint32(8,true),ha:dv.getFloat32(12,true)||1,tr:new Uint32Array(ab,16,n),lon:new Uint16Array(ab,16+4*n,n),lat:new Uint16Array(ab,16+6*n,n),tall:new Uint8Array(ab,16+8*n,n),mean:new Uint8Array(ab,16+9*n,n)};tro.cache[k]=b;tro.order.push(k);while(tro.order.length>6)delete tro.cache[tro.order.shift()];if(tro.bk===k){tro.bx=b;troPaint()}}).catch(function(e){if(tro.bl===k)tro.bl='';dbgLog('trees far: '+(e&&e.message||e))})}
/* the sheet sits right over the picture it tints (dots and faces, or the coarse tiles), under every mark above */
function troPlace(){if(!tro.g){tro.g=document.createElementNS('http://www.w3.org/2000/svg','g');tro.g.setAttribute('class','tro')}var af=hi.on&&hi.g?hi.g:hexG||dots;if(tro.g.previousSibling!==af)af.parentNode.insertBefore(tro.g,af.nextSibling)}
function troPaint(){if(!troVis())return;troPlace();var bx=tro.bk&&tro.bx&&tro.bx.k===tro.bk?tro.bx:null,d=tro.d,pk=bx?bx.k:tro.bk&&tro.bx&&tro.pk===tro.bx.k?tro.pk/* the box of a moment ago stands until the new one lands */:d&&cells.length?'7|'+d.gen:'';if(pk&&pk===tro.pk){troChip();return}if(!pk){troChip();return}
 var b=[],i,k,o='';for(i=0;i<=TRO_B;i++)b[i]=[];
 if(bx){var C=[],S=[],v,sub=bx.res===8?2.6457513:7,dr=bx.res===8?.3334733:0;for(v=0;v<6;v++){C[v]=Math.cos(v*1.0471975512);S[v]=Math.sin(v*1.0471975512)}
  for(i=0;i<bx.n;i++){k=troBucket(bx.tr[i],bx.ha);if(!k)continue;var x=px(9+bx.lon[i]/65535*9),y=py(46+bx.lat[i]/65535*4),h=hexAt(x,y),R=h[1]/sub*HR,a=h[0]+dr,ca=Math.cos(a),sa=Math.sin(a),p='M';for(v=0;v<6;v++)p+=(x+R*(C[v]*ca-S[v]*sa)).toFixed(2)+' '+(y+R*(C[v]*sa+S[v]*ca)).toFixed(2)+(v<5?'L':'Z');b[k].push(p)}}
 else{var tr=d.trees,ha=d.cell_ha||516;for(i=0;i<cells.length&&i<tr.length;i++){k=troBucket(tr[i],ha);if(k)b[k].push(faceD(i))}}
 for(k=1;k<=TRO_B;k++)if(b[k].length)o+='<path opacity="'+(TRO_A*k/TRO_B).toFixed(2)+'" d="'+b[k].join('')+'"/>';tro.g.innerHTML=o;tro.pk=pk;troChip();clearTimeout(tro.lt);tro.lt=setTimeout(hiLegend,60)}
/* the trees in view: the box's hexagons when the sheet shows them, else the res-7 cells; all of Austria = the index's own total */
function troSum(){var d=tro.d,bx=tro.bx&&tro.pk===tro.bx.k?tro.bx:null,n=0,tm=0,ms=0,i,x,y,x1=vb.x+vb.w,y1=vb.y+vb.h;
 if(bx){for(i=0;i<bx.n;i++){x=px(9+bx.lon[i]/65535*9);y=py(46+bx.lat[i]/65535*4);if(x<vb.x||x>x1||y<vb.y||y>y1)continue;n+=bx.tr[i];ms+=bx.tr[i]*bx.mean[i]/4;if(bx.tall[i]>tm)tm=bx.tall[i]}return{n:n,tall:tm,mean:n?ms/n:0,all:false,res:bx.res}}
 if(!d||!cells.length)return null;var all=true,tr=d.trees;for(i=0;i<cells.length&&i<tr.length;i++){var c=cells[i];if(c[0]<vb.x||c[0]>x1||c[1]<vb.y||c[1]>y1){all=false;continue}n+=tr[i];ms+=tr[i]*d.mean_m[i];if(d.tallest_m[i]>tm)tm=d.tallest_m[i]}
 if(all)return{n:d.total.trees,tall:d.total.tallest_m,mean:d.total.mean_height_m,all:true,res:7};return{n:n,tall:tm,mean:n?ms/n:0,all:false,res:7}}
function troN(s){return s.all?fmt(s.n):s.n>=1e4?bigN(s.n):fmt(s.n)}
function troNote(){if(!hi.tree)return'';var n=0,ap='';if(troVis()){var s=troSum();if(!s)return'';n=s.n;ap=s.res===7&&!s.all?'\u2248\u202f':''}else{var t=hiLOD()===2?treeSum():apSum();if(!t)return'';n=t.n}return n?'<span class="n">\u00b7 '+ap+bigN(n)+' trees</span>':''}
function troChip(){var far=troVis(),on=far&&!ivAvail(),s=on?troSum():null;if(hi.on&&tN.classList.contains('iv')){var nh=troNote();if(nh!==tro.nh){tro.nh=nh;if(!(iv.on&&tip.classList.contains('iv')))ivNote()}}if(!s||!s.n){if(tro.el&&tro.el.classList.contains('on'))tro.el.classList.remove('on');return}if(!tro.el){tro.el=document.createElement('div');tro.el.className='glyph-trn';tro.el.setAttribute('aria-live','off');main.appendChild(tro.el)}
 var h='<b>trees</b> \u00b7 '+(s.all?'':s.res===7?'\u2248\u202f':'')+troN(s)+(s.all?' <span class="w0">in Austria</span>':' in view')+(s.tall?' <span class="w0">\u00b7 tallest '+Math.round(s.tall)+'\u202fm</span>':'');if(h!==tro.eh){tro.eh=h;tro.el.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m17 14 3 3.3a1 1 0 0 1-.7 1.7H4.7a1 1 0 0 1-.7-1.7L7 14h-.3a1 1 0 0 1-.7-1.7L9 9h-.2A1 1 0 0 1 8 7.3L12 3l4 4.3a1 1 0 0 1-.8 1.7H15l3 3.3a1 1 0 0 1-.7 1.7H17Z"/><path d="M12 22v-3"/></svg><span>'+h+'</span>'}
 tro.el.classList.add('on')}
/* legend block (card / in-view sheet) and the res-7 card's row */
function troBlock(){var s=troSum();if(!s)return'<div class="sh ovh"><span>in view \u00b7 trees <i>tree tops per hexagon \u00b7 {OBS_NAME}</i></span></div><div class="nt mut">'+(tro.err?'the tree index is not at hand \u00b7 zoom in for the crowns':'loading trees'+ldots())+'</div>';
 return'<div class="sh ovh"><span>in view \u00b7 trees <i>LiDAR tree tops \u2265 3\u202fm per hexagon \u00b7 greener = denser \u00b7 {OBS_NAME}</i></span>'+(s.tall?'<em class="o">'+Math.round(s.tall)+'\u202fm tallest</em>':'')+'</div><div class="nt">'+(s.n?(s.res===7&&!s.all?'\u2248\u202f':'')+'<b>'+fmt(s.n)+'</b> trees \u00b7 mean height <b>'+s.mean.toFixed(1)+'\u202fm</b>'+(s.all?' \u00b7 Austria':''):'<span class="mut">no tree in view</span>')+'</div>'}
function troDotLine(i){var d=tro.d;if(!hi.tree||!d||!(d.trees[i]>0))return'';return'<div class="rw"><span class="lb">trees</span><span class="vl"><b>'+fmt(d.trees[i])+'</b> \u00b7 '+Math.round(d.trees[i]/(d.cell_ha||516))+'\u202f/\u202fha \u00b7 mean '+d.mean_m[i].toFixed(1)+'\u202fm \u00b7 tallest '+d.tallest_m[i]+'\u202fm</span></div>'}
/* a selection's trees (KG, Gemeinde, Bezirk, Land, Natura 2000 site, a combination of KGs): one card row — the height distribution as a sparkline, the range, the mean, the count. Asked once per unit, the card re-renders when it lands; a unit without an answer has no row */
var tru={c:{},n:0};
function troSpark(bands,edges,tall){var n=bands.length,d=[],mx=0,p=0,i,w;for(i=0;i<n;i++){w=i+1<n?edges[i+1]-edges[i]:5;d[i]=bands[i]/w;if(d[i]>mx){mx=d[i];p=i}}if(!(mx>0))return'';var s='<svg class="trspark" preserveAspectRatio="none" viewBox="0 0 '+(n*4-1)+' 12" role="img" aria-label="trees by height"><title>trees by height \u00b7 5\u202fm bands from '+edges[0]+'\u202fm \u00b7 most are '+edges[p]+'\u2013'+(p+1<n?edges[p+1]:Math.round(tall))+'\u202fm</title>';for(i=0;i<n;i++){var bh=Math.max(.6,d[i]/mx*12);s+='<rect x="'+i*4+'" y="'+(12-bh).toFixed(1)+'" width="3" height="'+bh.toFixed(1)+'"/>'}return s+'</svg>'}
function troUnitRow(s){var tok=selTok(s),d=tru.c[tok];if(d===undefined){tru.c[tok]=0;if(++tru.n>60){tru.c={};tru.n=1;tru.c[tok]=0}fetch('/api/v1/ne/glyph/trees?u='+encodeURIComponent(tok),{credentials:'omit'}).then(function(r){return r.ok?r.json():null}).then(function(j){tru.c[tok]=j&&j.trees>0&&j.bands?j:null;if(tru.c[tok]&&picked&&pk&&(sel||asel)&&selTok(sel||asel)===tok)recard()}).catch(function(){delete tru.c[tok]});return''}
 if(!d)return'';return'<div class="rw"><span class="lb">trees</span><span class="vl">'+troSpark(d.bands,d.edges_m,d.tallest_m)+' '+d.edges_m[0]+'\u2013'+Math.round(d.tallest_m)+'\u202fm<span class="sep"></span>mean '+d.mean_height_m.toFixed(1)+'\u202fm<span class="sep"></span><span class="mut">'+fmt(d.trees)+' trees</span></span></div>'}
troSync();
`
